  public static Cavalierctl.AgenticConfig agenticConfigFromBytes(byte[] data)
      throws ProtoException {
    if (data == null || data.length == 0) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "data is null or empty");
    }
    String dataStr = new String(data).trim();
    if (dataStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "empty data after trimming");
    }
    if (dataStr.startsWith("{") || dataStr.startsWith("[")) {
      try {
        return agenticConfigFromJson(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains(":") && !dataStr.contains("=")) {
      try {
        return agenticConfigFromYaml(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains("=")) {
      try {
        return agenticConfigFromToml(dataStr);
      } catch (Exception e) {
        // Fall through to try binary
      }
    }
    try {
      return agenticConfigFromBinary(data);
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to parse AgenticConfig: unsupported format or invalid data: " + e.getMessage(),
          e);
    }
  }

  public static Cavalierctl.AgenticConfig agenticConfigFromJson(String json) throws ProtoException {
    if (json == null || json.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "json is null or empty");
    }
    try {
      Cavalierctl.AgenticConfig.Builder builder = Cavalierctl.AgenticConfig.newBuilder();
      Gson gson = new Gson();
      JsonObject obj = gson.fromJson(json, JsonObject.class);
      JsonElement flushIntervalMsEl =
          obj.has("flushIntervalMs") ? obj.get("flushIntervalMs") : obj.get("flush_interval_ms");
      if (flushIntervalMsEl != null && !flushIntervalMsEl.isJsonNull()) {
        if (flushIntervalMsEl.isJsonPrimitive()) {
          builder.setFlushIntervalMs(flushIntervalMsEl.getAsInt());
        }
      }
      JsonElement batchSizeEl = obj.has("batchSize") ? obj.get("batchSize") : obj.get("batch_size");
      if (batchSizeEl != null && !batchSizeEl.isJsonNull()) {
        if (batchSizeEl.isJsonPrimitive()) {
          builder.setBatchSize(batchSizeEl.getAsInt());
        }
      }
      JsonElement maxEventPayloadBytesEl =
          obj.has("maxEventPayloadBytes")
              ? obj.get("maxEventPayloadBytes")
              : obj.get("max_event_payload_bytes");
      if (maxEventPayloadBytesEl != null && !maxEventPayloadBytesEl.isJsonNull()) {
        if (maxEventPayloadBytesEl.isJsonPrimitive()) {
          builder.setMaxEventPayloadBytes(maxEventPayloadBytesEl.getAsInt());
        }
      }
      JsonElement filePatternExcludelistEl =
          obj.has("filePatternExcludelist")
              ? obj.get("filePatternExcludelist")
              : obj.get("file_pattern_excludelist");
      if (filePatternExcludelistEl != null && !filePatternExcludelistEl.isJsonNull()) {
        if (filePatternExcludelistEl.isJsonArray()) {
          for (JsonElement item : filePatternExcludelistEl.getAsJsonArray()) {
            if (item.isJsonPrimitive()) {
              builder.addFilePatternExcludelist(item.getAsString());
            }
          }
        }
      }
      JsonElement spoolMaxBytesEl =
          obj.has("spoolMaxBytes") ? obj.get("spoolMaxBytes") : obj.get("spool_max_bytes");
      if (spoolMaxBytesEl != null && !spoolMaxBytesEl.isJsonNull()) {
        if (spoolMaxBytesEl.isJsonPrimitive()) {
          builder.setSpoolMaxBytes(spoolMaxBytesEl.getAsLong());
        }
      }
      return builder.build();
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          "Failed to parse AgenticConfig from JSON: " + e.getMessage(),
          e);
    }
  }

