  public static String agenticConfigToYaml(Cavalierctl.AgenticConfig msg) throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "AgenticConfig is null");
    }
    try {
      String json = agenticConfigToJson(msg);
      Gson gson = new Gson();
      Map<String, Object> map =
          gson.fromJson(
              json, new com.google.gson.reflect.TypeToken<Map<String, Object>>() {}.getType());
      Yaml yaml = new Yaml();
      return yaml.dump(map);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to serialize AgenticConfig to YAML: " + e.getMessage(),
          e);
    }
  }

  public static Cavalierctl.AgenticConfig agenticConfigFromYaml(String yamlStr)
      throws ProtoException {
    if (yamlStr == null || yamlStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "yamlStr is null or empty");
    }
    try {
      Yaml yaml = new Yaml();
      @SuppressWarnings("unchecked")
      Map<String, Object> map = (Map<String, Object>) yaml.load(yamlStr);
      Gson gson = new Gson();
      String json = gson.toJson(map);
      return agenticConfigFromJson(json);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to parse AgenticConfig from YAML: " + e.getMessage(), e);
    }
  }

  public static String agenticConfigToToml(Cavalierctl.AgenticConfig msg) throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "AgenticConfig is null");
    }
    try {
      String json = agenticConfigToJson(msg);
      Gson gson = new Gson();
      Map<String, Object> map =
          gson.fromJson(
              json, new com.google.gson.reflect.TypeToken<Map<String, Object>>() {}.getType());
      StringBuilder toml = new StringBuilder();
      if (map == null || map.isEmpty()) {
        return "# Empty AgenticConfig\n";
      }
      for (Map.Entry<String, Object> entry : map.entrySet()) {
        toml.append(entry.getKey()).append(" = ");
        if (entry.getValue() instanceof String) {
          toml.append("\"").append(entry.getValue()).append("\"");
        } else {
          toml.append(entry.getValue());
        }
        toml.append("\n");
      }
      return toml.toString();
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to serialize AgenticConfig to TOML: " + e.getMessage(),
          e);
    }
  }

  public static Cavalierctl.AgenticConfig agenticConfigFromToml(String tomlStr)
      throws ProtoException {
    if (tomlStr == null || tomlStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "tomlStr is null or empty");
    }
    try {
      Toml toml = new Toml().read(tomlStr);
      Map<String, Object> map = toml.toMap();
      Gson gson = new Gson();
      String json = gson.toJson(map);
      return agenticConfigFromJson(json);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to parse AgenticConfig from TOML: " + e.getMessage(), e);
    }
  }

  // ============ Validation ============
  public static void validateConfig(Cavalierctl.Config msg) throws ProtoException {
    if (msg == null) {
      return;
    }
  }

  public static void validateProfileConfig(Cavalierctl.ProfileConfig msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate currentProfile (assert_max_length: 128)
    if (msg.getCurrentProfile().length() > 128) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field currentProfile must be at most 128 characters, got: %d",
              msg.getCurrentProfile().length()));
    }
  }

  public static void validateAgenticConfig(Cavalierctl.AgenticConfig msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate flushIntervalMs (assert_ge: 100)
    if (msg.getFlushIntervalMs() < 100) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field flushIntervalMs must be >= 100, got: %s", msg.getFlushIntervalMs()));
    }
    // Validate flushIntervalMs (assert_le: 60000)
    if (msg.getFlushIntervalMs() > 60000) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field flushIntervalMs must be <= 60000, got: %s", msg.getFlushIntervalMs()));
    }
    // Validate batchSize (assert_ge: 1)
    if (msg.getBatchSize() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field batchSize must be >= 1, got: %s", msg.getBatchSize()));
    }
    // Validate batchSize (assert_le: 10000)
    if (msg.getBatchSize() > 10000) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field batchSize must be <= 10000, got: %s", msg.getBatchSize()));
    }
    // Validate maxEventPayloadBytes (assert_ge: 1024)
    if (msg.getMaxEventPayloadBytes() < 1024) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field maxEventPayloadBytes must be >= 1024, got: %s",
              msg.getMaxEventPayloadBytes()));
    }
    // Validate maxEventPayloadBytes (assert_le: 1048576)
    if (msg.getMaxEventPayloadBytes() > 1048576) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field maxEventPayloadBytes must be <= 1048576, got: %s",
              msg.getMaxEventPayloadBytes()));
    }
    // Validate filePatternExcludelist (assert_max_length: 512)
    if (msg.getFilePatternExcludelistCount() > 512) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field filePatternExcludelist must have at most 512 elements, got: %d",
              msg.getFilePatternExcludelistCount()));
    }
    // Validate spoolMaxBytes (assert_ge: 1024)
    if (msg.getSpoolMaxBytes() < 1024L) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field spoolMaxBytes must be >= 1024, got: %s", msg.getSpoolMaxBytes()));
    }
    // Validate spoolMaxBytes (assert_le: 2147483648)
    if (msg.getSpoolMaxBytes() > 2147483648L) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field spoolMaxBytes must be <= 2147483648, got: %s", msg.getSpoolMaxBytes()));
    }
  }

  // ============ TypeDefaults ============
  /** Applies default values to zero-valued fields of Config. */
  public static Cavalierctl.Config.Builder configDefaults(Cavalierctl.Config msg) {
    if (msg == null) {
      return null;
    }
    Cavalierctl.Config.Builder builder = msg.toBuilder();
    if (!msg.hasAgentic()) {
      builder.setAgentic(Cavalierctl.AgenticConfig.getDefaultInstance());
    }
    builder.setAgentic(agenticConfigDefaults(builder.getAgentic()).build());
    return builder;
  }

