    if (msg.getMaxEventPayloadBytes() == 0) {
      builder.setMaxEventPayloadBytes((int) Helpers.DEFAULT_MAX_EVENT_PAYLOAD_BYTES);
    }
    if (msg.getSpoolMaxBytes() == 0) {
      builder.setSpoolMaxBytes(Helpers.DEFAULT_SPOOL_MAX_BYTES);
    }
