  // ============ Merge ============
  public static Cavalierctl.Config.Builder mergeConfig(
      Cavalierctl.Config dst, Cavalierctl.Config src) {
    Cavalierctl.Config.Builder builder = dst.toBuilder();
    if (!dst.hasConnection() && src.hasConnection()) {
      builder.setConnection(src.getConnection());
    }
    if (dst.getFormatValue() == 0) {
      builder.setFormatValue(src.getFormatValue());
    }
    if (!dst.hasAgentic() && src.hasAgentic()) {
      builder.setAgentic(src.getAgentic());
    } else if (dst.hasAgentic() && src.hasAgentic()) {
      builder.setAgentic(mergeAgenticConfig(dst.getAgentic(), src.getAgentic()).build());
    }
    if (!dst.getDirectMode()) {
      builder.setDirectMode(src.getDirectMode());
    }
    return builder;
  }

  public static Cavalierctl.ProfileConfig.Builder mergeProfileConfig(
      Cavalierctl.ProfileConfig dst, Cavalierctl.ProfileConfig src) {
    Cavalierctl.ProfileConfig.Builder builder = dst.toBuilder();
    if (dst.getCurrentProfile().isEmpty()) {
      builder.setCurrentProfile(src.getCurrentProfile());
    }
    if (dst.getProfilesMap().isEmpty()) {
      builder.putAllProfiles(src.getProfilesMap());
    } else {
      for (String mk : src.getProfilesMap().keySet()) {
        if (dst.getProfilesMap().containsKey(mk)) {
          builder.putProfiles(
              mk, mergeConfig(dst.getProfilesMap().get(mk), src.getProfilesMap().get(mk)).build());
        } else {
          builder.putProfiles(mk, src.getProfilesMap().get(mk));
        }
      }
    }
    return builder;
  }

  public static Cavalierctl.AgenticConfig.Builder mergeAgenticConfig(
      Cavalierctl.AgenticConfig dst, Cavalierctl.AgenticConfig src) {
    Cavalierctl.AgenticConfig.Builder builder = dst.toBuilder();
    if (dst.getFlushIntervalMs() == 0) {
      builder.setFlushIntervalMs(src.getFlushIntervalMs());
    }
    if (dst.getBatchSize() == 0) {
      builder.setBatchSize(src.getBatchSize());
    }
    if (dst.getMaxEventPayloadBytes() == 0) {
      builder.setMaxEventPayloadBytes(src.getMaxEventPayloadBytes());
    }
    if (dst.getFilePatternExcludelistList().isEmpty()) {
      builder.addAllFilePatternExcludelist(src.getFilePatternExcludelistList());
    }
    if (dst.getSpoolMaxBytes() == 0) {
      builder.setSpoolMaxBytes(src.getSpoolMaxBytes());
    }
    return builder;
  }

  // ============ EnvVar ============
  public static Map<String, String> configToEnvVar(Cavalierctl.Config msg) {
    Map<String, String> result = new HashMap<>();
    if (msg.hasConnection()) {
      result.putAll(
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.grpcconfig
              .Helpers.configToEnvVar(msg.getConnection()));
    }
    result.put(
        "PROTO_CONFIG_FORMAT",
        com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.outputformat
            .Helpers.outputFormatToString(msg.getFormat()));
    if (msg.hasAgentic()) {
      result.putAll(agenticConfigToEnvVar(msg.getAgentic()));
    }
    result.put("PROTO_CONFIG_DIRECT_MODE", String.valueOf(msg.getDirectMode()));
    return result;
  }

  public static Cavalierctl.Config.Builder configFromEnvVar(Map<String, String> env) {
    Cavalierctl.Config.Builder builder = Cavalierctl.Config.newBuilder();
    String val;
    {
      var sub =
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.grpcconfig
              .Helpers.configFromEnvVar(env)
              .build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setConnection(sub);
      }
    }
    val = env.get("PROTO_CONFIG_FORMAT");
    if (val != null && !val.isEmpty()) {
      builder.setFormat(
          com.gitlab.secondstarcavalier.controlplane.services.kernel.tacplus.types.libs.outputformat
              .Helpers.parseOutputFormat(val));
    }
    {
      var sub = agenticConfigFromEnvVar(env).build();
      if (!sub.equals(sub.getDefaultInstanceForType())) {
        builder.setAgentic(sub);
      }
    }
    val = env.get("PROTO_CONFIG_DIRECT_MODE");
    if (val != null && !val.isEmpty()) {
      builder.setDirectMode(Boolean.parseBoolean(val));
    }
    return builder;
  }

  public static Map<String, String> profileConfigToEnvVar(Cavalierctl.ProfileConfig msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_PROFILE_CONFIG_CURRENT_PROFILE", msg.getCurrentProfile());
    return result;
  }

  public static Cavalierctl.ProfileConfig.Builder profileConfigFromEnvVar(Map<String, String> env) {
    Cavalierctl.ProfileConfig.Builder builder = Cavalierctl.ProfileConfig.newBuilder();
    String val;
    val = env.get("PROTO_PROFILE_CONFIG_CURRENT_PROFILE");
    if (val != null && !val.isEmpty()) {
      builder.setCurrentProfile(val);
    }
    return builder;
  }

  public static Map<String, String> agenticConfigToEnvVar(Cavalierctl.AgenticConfig msg) {
    Map<String, String> result = new HashMap<>();
    result.put("PROTO_AGENTIC_CONFIG_FLUSH_INTERVAL_MS", String.valueOf(msg.getFlushIntervalMs()));
    result.put("PROTO_AGENTIC_CONFIG_BATCH_SIZE", String.valueOf(msg.getBatchSize()));
    result.put(
        "PROTO_AGENTIC_CONFIG_MAX_EVENT_PAYLOAD_BYTES",
        String.valueOf(msg.getMaxEventPayloadBytes()));
    if (!msg.getFilePatternExcludelistList().isEmpty()) {
      result.put(
          "PROTO_AGENTIC_CONFIG_FILE_PATTERN_EXCLUDELIST",
          String.join(",", msg.getFilePatternExcludelistList()));
    }
    result.put("PROTO_AGENTIC_CONFIG_SPOOL_MAX_BYTES", String.valueOf(msg.getSpoolMaxBytes()));
    return result;
  }

  public static Cavalierctl.AgenticConfig.Builder agenticConfigFromEnvVar(Map<String, String> env) {
    Cavalierctl.AgenticConfig.Builder builder = Cavalierctl.AgenticConfig.newBuilder();
    String val;
    val = env.get("PROTO_AGENTIC_CONFIG_FLUSH_INTERVAL_MS");
    if (val != null && !val.isEmpty()) {
      builder.setFlushIntervalMs(Integer.parseInt(val));
    }
    val = env.get("PROTO_AGENTIC_CONFIG_BATCH_SIZE");
    if (val != null && !val.isEmpty()) {
      builder.setBatchSize(Integer.parseInt(val));
    }
    val = env.get("PROTO_AGENTIC_CONFIG_MAX_EVENT_PAYLOAD_BYTES");
    if (val != null && !val.isEmpty()) {
      builder.setMaxEventPayloadBytes(Integer.parseInt(val));
    }
    val = env.get("PROTO_AGENTIC_CONFIG_FILE_PATTERN_EXCLUDELIST");
    if (val != null && !val.isEmpty()) {
      builder.addAllFilePatternExcludelist(Arrays.asList(val.split(",")));
    }
    val = env.get("PROTO_AGENTIC_CONFIG_SPOOL_MAX_BYTES");
    if (val != null && !val.isEmpty()) {
      builder.setSpoolMaxBytes(Long.parseLong(val));
    }
    return builder;
  }
